PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?father ?fatherLabel ?paternalGrandmother ?paternalGrandmotherLabel WHERE {
  <http://dbpedia.org/resource/Gaston,_Duke_of_Orl%C3%A9ans> (dbo:father|dbp:father|dbo:parent|dbp:parent|dbp:parents|dbp:parent) ?father .
  OPTIONAL {
    ?father (dbo:mother|dbp:mother|dbo:parent|dbp:parent|dbp:mother) ?paternalGrandmother .
  }
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = 'en') }
  OPTIONAL { ?paternalGrandmother rdfs:label ?paternalGrandmotherLabel . FILTER(lang(?paternalGrandmotherLabel) = 'en') }
}
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?p ?pLabel WHERE {
  <http://dbpedia.org/resource/Gaston,_Duke_of_Orl%C3%A9ans> ?p ?o .
  OPTIONAL { ?p rdfs:label ?pLabel . FILTER(lang(?pLabel) = 'en') }
}
LIMIT 200

